package com.logistics.order;
import org.springframework.boot.*;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.context.annotation.Bean;import org.springframework.scheduling.annotation.EnableScheduling;import org.springframework.amqp.core.*;import org.springframework.amqp.support.converter.Jackson2JsonMessageConverter;
@SpringBootApplication @EnableScheduling public class OrderServiceApplication { public static void main(String[] a){SpringApplication.run(OrderServiceApplication.class,a);} @Bean TopicExchange events(){return new TopicExchange("logistics.events", true, false);} @Bean Jackson2JsonMessageConverter jsonConverter(){return new Jackson2JsonMessageConverter();} @Bean Queue resultQueue(){return QueueBuilder.durable("order.inventory-results").withArgument("x-dead-letter-exchange","logistics.events.dlx").build();} @Bean Binding resultBinding(Queue resultQueue, TopicExchange events){return BindingBuilder.bind(resultQueue).to(events).with("InventoryReserved");} @Bean Binding rejectedBinding(Queue resultQueue, TopicExchange events){return BindingBuilder.bind(resultQueue).to(events).with("InventoryRejected");} @Bean Queue deliveredQueue(){return QueueBuilder.durable("order.shipment-delivered").build();} @Bean Binding deliveredBinding(Queue deliveredQueue, TopicExchange events){return BindingBuilder.bind(deliveredQueue).to(events).with("ShipmentDelivered");} @Bean DirectExchange dlx(){return new DirectExchange("logistics.events.dlx");} @Bean Queue deadLetterQueue(){return QueueBuilder.durable("order.events.dlq").build();} @Bean Binding deadLetterBinding(){return BindingBuilder.bind(deadLetterQueue()).to(dlx()).with("order");} }

